<?php defined('ABSPATH') || exit; global $wpdb; $id = $job->ID; $applied = is_user_logged_in() ? $wpdb->get_var($wpdb->prepare('SELECT id FROM ' . tj_table('applications') . ' WHERE user_id=%d AND job_id=%d', get_current_user_id(), $id)) : null; ?>
<div class="tj-container"><p><a href="<?php echo esc_url(tj_url('viec-lam')); ?>">← <?php tj_e('Tất cả việc làm', 'All jobs'); ?></a></p><div class="tj-detail-grid"><article class="tj-panel"><span class="tj-eyebrow"><?php echo esc_html(tj_company_name($id)); ?></span><h1><?php echo esc_html(tj_title($id)); ?></h1><div class="tj-tags"><span><?php echo esc_html(tj_terms($id, 'location')); ?></span><span><?php echo esc_html(tj_terms($id, 'skill')); ?></span><span><?php echo esc_html(tj_meta($id, 'job_type')); ?></span></div><p class="tj-salary"><?php echo esc_html(tj_salary($id)); ?></p><h2><?php tj_e('Mô tả công việc', 'Job description'); ?></h2><div class="tj-prose"><?php echo wp_kses_post(wpautop(tj_content($id))); ?></div><h2><?php tj_e('Yêu cầu ứng viên', 'Requirements'); ?></h2><div class="tj-prose"><?php echo wp_kses_post(wpautop(tj_content($id, 'requirements'))); ?></div><?php if (tj_lang() === 'en' && !tj_meta($id, 'description_en')) { ?><p class="tj-muted">English translation unavailable. Showing Vietnamese content.</p><?php } ?></article><aside class="tj-panel tj-apply"><h2><?php tj_e('Ứng tuyển vị trí này', 'Apply for this job'); ?></h2><p><?php tj_e('Hạn nộp:', 'Apply by:'); ?> <strong><?php echo esc_html(tj_meta($id, 'deadline') ?: tj_t('Không giới hạn', 'Open-ended')); ?></strong></p>
<?php if (!tj_job_open($id)) { tj_empty(tj_t('Tin đã đóng hoặc hết hạn.', 'This job is closed or expired.')); } elseif (!is_user_logged_in()) { ?><a class="tj-button" href="<?php echo esc_url(tj_url('dang-nhap', ['next' => tj_job_url($id)])); ?>"><?php tj_e('Đăng nhập để ứng tuyển', 'Sign in to apply'); ?></a><?php } elseif ($applied) { ?><p class="tj-alert notice"><?php tj_e('Bạn đã ứng tuyển công việc này.', 'You have applied for this job.'); ?></p><a href="<?php echo esc_url(tj_url('tai-khoan/ung-tuyen', ['application' => $applied])); ?>"><?php tj_e('Xem hồ sơ đã gửi', 'View application'); ?></a><?php } elseif (tj_candidate()) {
tj_form_start('apply', 'tj-stack', true); tj_hidden('job_id', $id); $files = ['' => tj_t('Chọn CV hoặc tải mới bên dưới', 'Select a CV or upload below')]; foreach (tj_rows('files', 50, get_current_user_id()) as $file) { $files[$file['id']] = $file['original_name']; } tj_select('file_id', tj_t('CV đã lưu', 'Saved CV'), $files); tj_input('cv', tj_t('Tải CV mới (PDF/DOC/DOCX, ≤5 MB)', 'Upload CV (PDF/DOC/DOCX, ≤5 MB)'), '', 'file'); tj_textarea('letter', tj_t('Lời giới thiệu', 'Cover letter')); ?><label class="tj-check"><input type="checkbox" name="consent" value="1" required> <span><?php tj_e('Tôi đồng ý gửi thông tin và CV cho nhà tuyển dụng.', 'I consent to submitting my information and CV to the recruiter.'); ?></span></label><?php tj_button('Nộp hồ sơ', 'Submit application'); ?></form><p class="tj-muted"><a href="<?php echo esc_url(tj_url('tai-khoan/ho-so')); ?>"><?php tj_e('Kiểm tra thông tin cá nhân trước khi gửi', 'Review your profile before applying'); ?></a></p><?php } ?>
<?php if (tj_candidate()) { $saved = $wpdb->get_var($wpdb->prepare('SELECT id FROM ' . tj_table('saved') . ' WHERE user_id=%d AND job_id=%d', get_current_user_id(), $id)); tj_form_start('save_job_toggle'); tj_hidden('job_id', $id); tj_button($saved ? 'Bỏ lưu việc làm' : 'Lưu việc làm', $saved ? 'Unsave job' : 'Save job', 'secondary'); echo '</form>'; } ?></aside></div></div>
